python3 - <<'PY'
import pathlib
p = pathlib.Path('src/codegen/lower_inst/builtins/io/phar_read.rs')
t = p.read_text()
old = '''            let builtin = crate::types::stream_constants::STREAM_WRAPPERS
                .iter()
                .any(|known| *known == scheme)
                || scheme == "compress.zlib"
                || scheme == "compress.bzip2";'''
new = '''            // `compress.zlib` and `compress.bzip2` are NOT counted as built-in here, though the
            // opener knows them: the plain byte reader below has no case for either, so treating
            // them as built-in sent them to a reader that opens the URL as a FILENAME.
            // `file_get_contents("compress.zlib://f.gz")` answered `Failed to open stream: No
            // such file or directory` where `fopen()` on the same URL read it — measured against
            // `php -n` 8.5.6, which decompresses. Delegating to the opener is what php-src does:
            // `file_get_contents` is `php_stream_open_wrapper` followed by
            // `_php_stream_copy_to_mem`, so every scheme the opener knows is readable by
            // definition.
            let builtin = crate::types::stream_constants::STREAM_WRAPPERS
                .iter()
                .any(|known| *known == scheme);'''
assert t.count(old) == 1
p.write_text(t.replace(old, new))
print('phar_read.rs: the compress schemes take the opener route')
PY
